const req = $('Seed').first().json.body || {};
const keys = Array.isArray(req.keys) ? req.keys
  : (req.set === 'all' ? EMAILS.map(e => e.key) : EMAILS.filter(e => e.loom).map(e => e.key));
const rows = $input.all().map(i => i.json).filter(r => r.message_id);
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const out = [];
for (const k of keys) {
  const e = EMAILS.find(x => x.key === k);
  if (!e) throw new Error('Unknown test email: ' + k);
  let parentId = '';
  if (e.reply_to) {
    const parent = EMAILS.find(x => x.key === e.reply_to);
    const prow = rows.filter(r => r.direction !== 'outbound' && r.from_email === parent.from_email && r.subject === parent.subject).pop();
    if (!prow) throw new Error('Send "' + e.reply_to + '" first: "' + k + '" is a reply on that thread');
    parentId = prow.rfc_message_id;
  }
  const headers = [
    'From: "' + e.from_name + '" <' + e.from_email + '>',
    'To: daniel+support@thatsautomated.com',
    'Subject: =?UTF-8?B?' + b64(e.subject) + '?=',
    'Date: ' + new Date().toUTCString(),
    'Message-ID: <p6-' + k + '-' + Date.now() + '-' + out.length + '@thatsautomated.test>',
    parentId ? 'In-Reply-To: ' + parentId : '',
    parentId ? 'References: ' + parentId : '',
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset=UTF-8',
    'Content-Transfer-Encoding: base64',
  ].filter(Boolean);
  const mime = headers.join('\r\n') + '\r\n\r\n' + b64(e.body.replace(/\r?\n/g, '\r\n')).replace(/(.{76})/g, '$1\r\n');
  // Gmail's import call threads a reply by its In-Reply-To/References headers and the Re: subject.
  const body = { raw: b64(mime).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''), labelIds: ['INBOX', 'UNREAD', 'Label_4'] };
  out.push({ json: { key: k, request: body } });
}
return out;
